// Flat array for components that need a flat list
export const FLAT_ALL_REVIEWS: any[] = Object.entries(ALL_BIDI_REVIEWS).flatMap(([bidiId, items]) =>
  items.map(item => ({
    id: item.id,
    bidiId: bidiId,
    bidiName: bidiId,
    userName: item.author,
    userRole: item.role,
    location: item.location,
    rating: item.rating,
    date: item.date,
    comment: item.comment,
    funnyEffectWitnessed: item.highlight || item.alienNote || '',
    helpfulCount: 45,
    avatarSeed: item.author,
    verifiedPurchase: item.verified,
    isAlien: item.isAlien,
    alienNote: item.alienNote,
    newsUpdate: item.newsUpdate
  }))
);
